# Add interactive gallery sourced from privacy-redacted original images.
gallery='''<script>
(function(){
const shots=__IMAGES__;
const titles=['准备素材','排版定制','智能检测','设计稿校对','生成交付','多设计稿批处理'];
const descriptions=['选择 PSD / PSB 进行只读扫描，导入已有多语言译文表。','右侧抽屉管理按语言的字体、行距、字距与本地保存。','逐语言提示与原文相同、重复和可能需要人工确认的译文。','对账缺译、确认保留原文，并在执行前检查 Photoshop 环境。','确认文件名、目标语言和费用后再执行，留存交付结果。','批量模式按 SKU / 设计文件管理，逐份扫描并复核后生成。'];
let current=0;let overlay=null;
function show(i){current=i;const pic=document.getElementById('v12ProofImage');if(!pic)return;pic.src=shots[i];pic.dataset.portrait=i===1?'1':'0';pic.alt='图译工坊 '+titles[i]+' 实际界面截图（脱敏）';const t=document.getElementById('v12ProofTitle'),d=document.getElementById('v12ProofDesc'),lnk=document.getElementById('v12ProofLink');if(t)t.textContent='当前工作台 / '+titles[i];if(d)d.textContent=descriptions[i];if(lnk)lnk.href=i===1?'#/studio/type':i===5?'#/studio/batch':'#/studio/single';document.querySelectorAll('[data-proof-tab]').forEach(b=>{const on=Number(b.dataset.proofTab)===i;b.classList.toggle('active',on);b.setAttribute('aria-selected',String(on))})}
const t=document.getElementById('v12TypePhoto');if(t)t.src=shots[1];const t2=document.getElementById('v12TypePagePhoto');if(t2)t2.src=shots[1];
document.addEventListener('click',e=>{const tab=e.target.closest('[data-proof-tab]');if(tab){show(Number(tab.dataset.proofTab));return}if(e.target.closest('#v12ProofZoom')){if(overlay)return;overlay=document.createElement('div');overlay.id='v12ProofOverlay';overlay.style.cssText='position:fixed;z-index:9999;inset:0;background:#0d1713e8;display:flex;align-items:center;justify-content:center;padding:35px;cursor:zoom-out';overlay.innerHTML='<img alt="脱敏原始界面截图" style="max-width:100%;max-height:100%;object-fit:contain;border-radius:8px" src="'+shots[current]+'">';overlay.addEventListener('click',()=>{overlay.remove();overlay=null});document.body.appendChild(overlay);return}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&overlay){overlay.remove();overlay=null}});
show(0)
})();
</script>'''.replace('__IMAGES__',json.dumps(images,ensure_ascii=False))
